// PAT Configuration - Edit these values
const config = {
  // Tableau Cloud Settings
  tableau: {
    baseUrl: 'https://prod-apnortheast-a.online.tableau.com',
    siteContentUrl: 'tableauadmin59b92d016b'
  },

  // Current PAT Information
  // ⚠️ 重要：每次手動輪替後需要更新這些值
  pat: {
    currentTokenName: 'n8n-token-2026',
    // PAT 創建日期 (ISO format)
    createdAt: '2025-11-28T00:00:00.000Z',
    // PAT 有效期為 180 天 (Tableau Cloud 預設)
    validityDays: 180,
    // 提前幾天開始提醒
    reminderThresholdDays: 14
  },

  // Slack Notification Settings
  slack: {
    channel: '#ops-test'
  }
};

// Calculate PAT expiry
const createdAt = new Date(config.pat.createdAt);
const expiresAt = new Date(createdAt);
expiresAt.setDate(expiresAt.getDate() + config.pat.validityDays);

const now = new Date();
const daysRemaining = Math.floor((expiresAt - now) / (1000 * 60 * 60 * 24));
const needsReminder = daysRemaining <= config.pat.reminderThresholdDays;
const isExpired = daysRemaining <= 0;

const result = {
  ...config,
  status: {
    createdAt: createdAt.toISOString(),
    expiresAt: expiresAt.toISOString(),
    daysRemaining,
    needsReminder,
    isExpired,
    checkTime: now.toISOString()
  }
};

console.log(`PAT Status Check:`);
console.log(`  Token Name: ${config.pat.currentTokenName}`);
console.log(`  Created: ${createdAt.toISOString().slice(0, 10)}`);
console.log(`  Expires: ${expiresAt.toISOString().slice(0, 10)}`);
console.log(`  Days Remaining: ${daysRemaining}`);
console.log(`  Needs Reminder: ${needsReminder ? 'YES' : 'NO'}`);

return { json: result };

